// Тексты игры. Они зашифрованы, чтобы их нельзя было прочитать раньше времени. Сайт расшифровывает их сам.
(function () {
  var KEY = "viski-25-31-dekabrya-mrrr";
  function unveil(bytes, k) { var out = new Uint8Array(bytes.length); for (var i = 0; i < bytes.length; i++) out[i] = bytes[i] ^ k[i % k.length] ^ ((i * 131) & 255); return out; }
  function sha256sync(str) {
    // маленький SHA-256 для синхронной расшифровки текстов при загрузке страницы
    function r(n, x) { return (x >>> n) | (x << (32 - n)); }
    var K = [], H = [], p = 2, c = 0;
    function prime(n) { for (var d = 2; d * d <= n; d++) if (n % d === 0) return false; return true; }
    while (c < 64) { if (prime(p)) { if (c < 8) H[c] = (Math.pow(p, 1 / 2) * 4294967296) | 0; K[c] = (Math.pow(p, 1 / 3) * 4294967296) | 0; c++; } p++; }
    var m = new TextEncoder().encode(str), l = m.length, w = new Uint8Array(((l + 9 + 63) >> 6) << 6);
    w.set(m); w[l] = 0x80; var bits = l * 8; for (var i = 0; i < 4; i++) w[w.length - 1 - i] = (bits >>> (8 * i)) & 255;
    for (var o = 0; o < w.length; o += 64) {
      var W = new Array(64);
      for (i = 0; i < 16; i++) W[i] = (w[o + 4 * i] << 24) | (w[o + 4 * i + 1] << 16) | (w[o + 4 * i + 2] << 8) | w[o + 4 * i + 3];
      for (i = 16; i < 64; i++) { var s0 = r(7, W[i - 15]) ^ r(18, W[i - 15]) ^ (W[i - 15] >>> 3), s1 = r(17, W[i - 2]) ^ r(19, W[i - 2]) ^ (W[i - 2] >>> 10); W[i] = (W[i - 16] + s0 + W[i - 7] + s1) | 0; }
      var a = H[0], b = H[1], cc = H[2], d = H[3], e = H[4], f = H[5], g = H[6], h = H[7];
      for (i = 0; i < 64; i++) {
        var S1 = r(6, e) ^ r(11, e) ^ r(25, e), ch = (e & f) ^ (~e & g), t1 = (h + S1 + ch + K[i] + W[i]) | 0;
        var S0 = r(2, a) ^ r(13, a) ^ r(22, a), mj = (a & b) ^ (a & cc) ^ (b & cc), t2 = (S0 + mj) | 0;
        h = g; g = f; f = e; e = (d + t1) | 0; d = cc; cc = b; b = a; a = (t1 + t2) | 0;
      }
      H[0] = (H[0] + a) | 0; H[1] = (H[1] + b) | 0; H[2] = (H[2] + cc) | 0; H[3] = (H[3] + d) | 0; H[4] = (H[4] + e) | 0; H[5] = (H[5] + f) | 0; H[6] = (H[6] + g) | 0; H[7] = (H[7] + h) | 0;
    }
    var out = new Uint8Array(32); for (i = 0; i < 8; i++) for (var j = 0; j < 4; j++) out[4 * i + j] = (H[i] >>> (24 - 8 * j)) & 255;
    return out;
  }
  var k = sha256sync(KEY);
  var raw = atob(""), bytes = new Uint8Array(raw.length);
  for (var i = 0; i < raw.length; i++) bytes[i] = raw.charCodeAt(i);
  var obj = JSON.parse(new TextDecoder("utf-8").decode(unveil(bytes, k)));
  for (var name in obj) window[name] = obj[name];
  // картинки, которые лежат в зашифрованном виде (подарки)
  window.__veil = function (url, type) {
    return fetch(url).then(function (r) { return r.arrayBuffer(); }).then(function (buf) {
      return URL.createObjectURL(new Blob([unveil(new Uint8Array(buf), k)], { type: type }));
    });
  };
})();
